class Solution {
  public int minChanges(int[] nums, int k) {
    int n = nums.length, pairs = n / 2;
    int[] exact = new int[k + 2]; // pairs whose difference is exactly d
    int[] reach = new int[k + 2]; // pairs whose largest reachable difference is d
    for (int i = 0; i < pairs; i++) {
      int a = nums[i], b = nums[n - 1 - i];
      exact[Math.abs(a - b)]++;
      reach[Math.max(Math.max(a, b), k - Math.min(a, b))]++;
    }
    for (int d = k - 1; d >= 0; d--)
      reach[d] += reach[d + 1]; // pairs that can reach difference >= d
    int best = Integer.MAX_VALUE;
    for (int target = 0; target <= k; target++) {
      // 0 changes if it already has the target difference, 1 if it can reach it, otherwise 2
      int cost = (pairs - exact[target]) + (pairs - reach[target]);
      best = Math.min(best, cost);
    }
    return best;
  }
}
